/**
 * @description TEMPLATE inbound handler. Rename it, change the checks and the record it creates, then type the class
 * name in the inbound event's Handler Class field. The caller sends POST /services/apexrest/integrationhub/v1/{Event Key}
 * with a JSON body; ctx.data is that body, parsed. Return inboundSuccess with the record Id to link the transaction
 * to the record, or inboundFailure with an HTTP status and a message.
 * @group Integration Hub
 */
public with sharing class IH_SampleInboundHandler implements IntegrationHub.IInboundHandler {

    private static final Integer BAD_REQUEST = 400;
    private static final Integer REFUSED = 422;

    /**
     * @description Creates a Case from {"subject": "...", "description": "..."}.
     * @param ctx the inbound call
     * @return success with the new record, or 400/422 with the reason
     */
    public IntegrationHub.InboundResult handle(IntegrationHub.InboundContext ctx) {
        Map<String, Object> req = ctx == null ? null : ctx.data;
        String subject = text(req, 'subject');
        if (String.isBlank(subject)) {
            return IntegrationHub.inboundFailure(BAD_REQUEST, 'subject is required.');
        }
        Case c = new Case(Subject = subject.left(255), Description = text(req, 'description'), Origin = 'Web');
        try {
            new Elevated().create(c);
            return IntegrationHub.inboundSuccess(c.Id, new Map<String, Object>{ 'caseId' => c.Id });
        } catch (DmlException e) {
            return IntegrationHub.inboundFailure(REFUSED, 'Not created: ' + e.getDmlMessage(0));
        }
    }

    /**
     * @description A text value from the body.
     * @param req the parsed body (may be null)
     * @param key the JSON key
     * @return the value as text, or null
     */
    @TestVisible
    private static String text(Map<String, Object> req, String key) {
        Object value = req == null ? null : req.get(key);
        return value == null ? null : String.valueOf(value);
    }

    /**
     * @description Creates the record in system mode: the integration user only needs Integration Hub Read.
     */
    private without sharing class Elevated {

        void create(SObject rec) {
            insert as system rec;
        }
    }
}
